-void write_utf8(unsigned code, std::ostream & ostr)
-{
-  static char buff[6];
-  unsigned count = 0;
-  // one byte (up to 7 bits)
-  if((code & 0xFFFFFF80) == 0)
-    {
-      buff[count++] = (char)code;
-    }
-  // two bytes (up to 11 bits)
-  else if((code & 0xFFFFF800) == 0)
-    {
-      char c;
-	  
-      c = 0xC0 | (0x1F & (code >> 6));
-      buff[count++] = c;
-      c = 0x80 | (0x3F & code);
-      buff[count++] = c;
-    }
-  // three bytes (up to 16 bits)
-  else if((code & 0xFFFF0000) == 0)
-    {
-      char c;
-
-      c = 0xE0 | (0xF & (code >> 12));
-      buff[count++] = c;
-      c = 0x80 | (0x3F & (code >> 6));
-      buff[count++] = c;
-      c = 0x80 | (0x3F & code);
-      buff[count++] = c;
-    }
-  // four bytes (up to 21 bits)
-  else if((code & 0xFFE00000) == 0)
-    {
-      char c;
-
-      c =  0xF0 | (0x7 & (code >> 18));
-      buff[count++] = c;
-      c = 0x80 | (0x3F & (code >> 12));
-      buff[count++] = c;
-      c = 0x80 | (0x3F & (code >> 6));
-      buff[count++] = c;
-      c = 0x80 | (0x3F & code);
-      buff[count++] = c;
-    }
-  // five bytes (up to 26 bits)
-  else if((code & 0xFC000000) == 0)
-    {
-      char c;
-
-      c = 0xF8 | (0x3 & (code >> 24));
-      buff[count++] = c;
-      c = 0x80 | (0x3F & (code >> 18));
-      buff[count++] = c;
-      c = 0x80 | (0x3F & (code >> 12));
-      buff[count++] = c;
-      c = 0x80 | (0x3F & (code >> 6));
-      buff[count++] = c;
-      c = 0x80 | (0x3F & code);
-      buff[count++] = c;
-    }
